-- Protocol/state fixtures only: injected service receipts are NOT real byte-upload evidence.
-- The entire new schema, synthetic identities and every record roll back.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select has_function('public','file_reserve',array['uuid','uuid','text','uuid','uuid','bigint','text','text','uuid'],'active member reserves private-file proposal');
insert into auth.users(id,email,email_confirmed_at) select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'synthetic-file-'||n||'@example.invalid',now() from generate_series(1,9)n;
insert into auth.sessions(id,user_id,not_after) select ('e2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now()+interval '1 day' from generate_series(1,9)n;
create function pg_temp.login(n int) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','e1000000-0000-4000-8000-'||lpad(n::text,12,'0'),'session_id','e2000000-0000-4000-8000-'||lpad(n::text,12,'0'),'exp',extract(epoch from now()+interval '1 hour'),'role','authenticated','is_anonymous',false)::text,true);end$$;
create function pg_temp.t() returns uuid language sql as $$select 'e3000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.game() returns uuid language sql as $$select 'e4000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.play() returns uuid language sql as $$select 'e5000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.id(n int) returns uuid language sql as $$select ('e6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table results(name text primary key,body jsonb);
grant select,insert,update on results to authenticated,service_role;
create function pg_temp.keep(n text,b jsonb) returns jsonb language plpgsql as $$begin insert into results values(n,b) on conflict(name) do update set body=excluded.body;return b;end$$;
create function pg_temp.body(n text) returns jsonb language sql as $$select body from results where name=n$$;
create function pg_temp.vid(n text) returns uuid language sql as $$select (body->>'id')::uuid from results where name=n$$;
create function pg_temp.rev(n text) returns bigint language sql as $$select (body->>'revision')::bigint from results where name=n$$;
insert into public.teams(id,name,owner_auth_uuid) values(pg_temp.t(),'SYNTHETIC PRIVATE FILE TEAM','e1000000-0000-4000-8000-000000000001');
insert into public.team_memberships(team_id,user_id,status) select pg_temp.t(),('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=6 then 'removed' else 'active' end from generate_series(2,9)n where n<>5;
insert into public.capability_grants(team_id,user_id,capability,issued_by) values
(pg_temp.t(),'e1000000-0000-4000-8000-000000000002','scouting.upload','e1000000-0000-4000-8000-000000000001'),
(pg_temp.t(),'e1000000-0000-4000-8000-000000000004','practice.upload','e1000000-0000-4000-8000-000000000001'),
(pg_temp.t(),'e1000000-0000-4000-8000-000000000007','practice.review','e1000000-0000-4000-8000-000000000001'),
(pg_temp.t(),'e1000000-0000-4000-8000-000000000008','scouting.read','e1000000-0000-4000-8000-000000000001');
insert into public.games(id,team_id,date,opponent,home_away,game_type,created_by) values(pg_temp.game(),pg_temp.t(),'2026-10-12','SYNTHETIC FILE OPPONENT','away','regularSeason','e1000000-0000-4000-8000-000000000001');
insert into public.plays(id,team_id,created_by) values(pg_temp.play(),pg_temp.t(),'e1000000-0000-4000-8000-000000000001');
insert into public.play_versions(id,team_id,play_id,author_user_id,status,title) values(pg_temp.id(100),pg_temp.t(),pg_temp.play(),'e1000000-0000-4000-8000-000000000001','published','SYNTHETIC FILE PLAY');
update public.plays set published_version_id=pg_temp.id(100) where id=pg_temp.play();
set local role authenticated;select pg_temp.login(2);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),100,'SYNTHETIC PDF')$$,'P0001',null,'unknown trusted capacity denies reservation');
select is((select count(*)::int from public.file_resources),0,'failed reservation creates no empty parent');
reset role;
-- Explicit trusted SYNTHETIC local allowance; never used as hosted Free feasibility.
update team_private.file_budget set known_until=now()+interval '1 day',storage_limit=2000,transfer_limit=2000 where id;
set local role authenticated;select pg_temp.login(3);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),100,'SYNTHETIC PDF')$$,'42501',null,'membership alone does not grant scouting upload');
select pg_temp.login(2);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),5242881,'OVERSIZED')$$,'22023',null,'PDF ceiling rejects5MiB plus one before storage');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),9223372036854775807,'OVERFLOW')$$,'22023',null,'largest bigint count cannot overflow budget math or bypass file ceiling');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),0,'EMPTY')$$,'22023',null,'zero bytes are not an uploaded document');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.id(999),pg_temp.id(11),100,'WRONG TARGET')$$,'22023',null,'nonexistent game cannot receive report');
select lives_ok($$select pg_temp.keep('pdf',public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),100,'SYNTHETIC PDF'))$$,'scouting contributor reserves game-linked immutable upload');
select is(public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),100,'SYNTHETIC PDF'),pg_temp.body('pdf'),'reservation retry returns exact stable record');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(11),101,'SYNTHETIC PDF')$$,'40001',null,'operation cannot silently change declared content');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(2),'scouting',pg_temp.game(),pg_temp.id(12),100,'SECOND')$$,'40001',null,'one active upload per account');
select throws_ok($$select public.file_transition(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.rev('pdf'),'submit')$$,'42501',null,'unvalidated reservation cannot be submitted');
select throws_ok($$select public.file_worker_finish(pg_temp.id(11),100,repeat('a',64),'application/pdf','{"pageCount":1}')$$,'42501',null,'client cannot forge trusted byte receipt');
select throws_ok($$insert into public.file_resources(id,team_id,kind,game_id) values(pg_temp.id(2),pg_temp.t(),'scouting',pg_temp.game())$$,'42501',null,'direct protected client write denied');
select throws_ok($$select * from team_private.file_budget$$,'42501',null,'trusted budget not client-readable');
select pg_temp.login(7);
select is((select count(*)::int from public.file_resource_versions),0,'legacy practice-review grant cannot inspect scouting pending bytes');
select pg_temp.login(2);
select lives_ok($$select public.file_upload_access(pg_temp.id(11))$$,'verified live contributor authorizes immediate worker access');
reset role;set local role service_role;
select lives_ok($$select public.file_worker_claim_upload(pg_temp.id(11),false)$$,'trusted worker claims immutable quarantine path');
select throws_ok($$select public.file_worker_claim_upload(pg_temp.id(11),false)$$,'40001',null,'uncertain upload cannot blindly retransfer');
select throws_ok($$select public.file_worker_finish(pg_temp.id(11),101,repeat('a',64),'application/pdf','{"pageCount":1}')$$,'22023',null,'trusted receipt must exactly match reserved length');
select lives_ok($$select pg_temp.keep('pdf',public.file_worker_finish(pg_temp.id(11),100,repeat('a',64),'application/pdf','{"pageCount":1}'))$$,'protocol fixture accepts exact service-only validated receipt');
select is(public.file_worker_finish(pg_temp.id(11),100,repeat('a',64),'application/pdf','{"pageCount":1}'),pg_temp.body('pdf'),'lost finalization reply retry cannot duplicate receipt');
select throws_ok($$select public.file_worker_finish(pg_temp.id(11),100,repeat('b',64),'application/pdf','{"pageCount":1}')$$,'40001',null,'accepted byte digest cannot change');
reset role;set local role authenticated;select pg_temp.login(2);
reset role;
update public.capability_grants set revoked_at=now() where user_id='e1000000-0000-4000-8000-000000000002' and capability='scouting.upload';
set local role authenticated;select pg_temp.login(2);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(30))$$,'42501',null,'revoked scouting contributor cannot fetch own pending bytes');
select is((select count(*)::int from public.file_resource_versions),0,'revoked scouting contributor loses protected pending metadata');
reset role;
update public.capability_grants set revoked_at=null where user_id='e1000000-0000-4000-8000-000000000002' and capability='scouting.upload';
set local role authenticated;select pg_temp.login(2);
select lives_ok($$select pg_temp.keep('pdf',public.file_save(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.rev('pdf'),'SYNTHETIC UPDATED PDF','TEST ONLY'))$$,'validated author edits metadata without byte replacement');
select throws_ok($$select public.file_save(pg_temp.t(),pg_temp.vid('pdf'),1,'STALE','')$$,'40001',null,'stale file save rejected');
select throws_ok($$select public.file_transition(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.rev('pdf'),'publish')$$,'42501',null,'scouting contributor requires owner approval');
select lives_ok($$select pg_temp.keep('pdf',public.file_transition(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.rev('pdf'),'submit'))$$,'validated scouting proposal submitted');
select pg_temp.login(8);
select is((select count(*)::int from public.file_resource_versions),0,'read grant does not expose unapproved report');
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(21))$$,'42501',null,'read grant cannot download pending report');
select pg_temp.login(1);
select lives_ok($$select pg_temp.keep('pdf',public.file_transition(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.rev('pdf'),'approve','SYNTHETIC OWNER APPROVAL'))$$,'owner atomically approves exact validated file version');
select is((select published_version_id from public.file_resources where id=pg_temp.id(1)),pg_temp.vid('pdf'),'approval updates published pointer');
select pg_temp.login(3);
select is((select count(*)::int from public.file_resource_versions),0,'ordinary member cannot read approved scouting without read grant');
select pg_temp.login(8);
select is((select byte_count from public.file_resource_versions where id=pg_temp.vid('pdf')),100::bigint,'authorized viewer sees exact stored metadata');
select lives_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(21))$$,'live read grant reserves complete file delivery');
reset role;set local role service_role;
select lives_ok($$select public.file_worker_claim_delivery(pg_temp.id(21))$$,'trusted delivery claims previously reserved allowance once');
select throws_ok($$select public.file_worker_claim_delivery(pg_temp.id(21))$$,'42501',null,'same delivery cannot transfer twice');
reset role;set local role authenticated;select pg_temp.login(8);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(21))$$,'40001',null,'client must create new operation for a real retransfer');
select pg_temp.login(2);
select pg_temp.keep('rejected',public.file_reserve(pg_temp.t(),pg_temp.id(7),'scouting',pg_temp.game(),pg_temp.id(17),100,'SYNTHETIC REJECTED HISTORY'));
select public.file_upload_access(pg_temp.id(17));
reset role;set local role service_role;
select public.file_worker_claim_upload(pg_temp.id(17),false);
select pg_temp.keep('rejected',public.file_worker_finish(pg_temp.id(17),100,repeat('e',64),'application/pdf','{"pageCount":1}'));
reset role;set local role authenticated;select pg_temp.login(2);
select pg_temp.keep('rejected',public.file_transition(pg_temp.t(),pg_temp.vid('rejected'),pg_temp.rev('rejected'),'submit'));
select pg_temp.login(1);
select pg_temp.keep('rejected',public.file_transition(pg_temp.t(),pg_temp.vid('rejected'),pg_temp.rev('rejected'),'reject','SYNTHETIC OWNER REJECTION'));
select pg_temp.login(2);
select is((select count(*)::int from public.file_resource_versions where id=pg_temp.vid('rejected')),0,'rejected scouting history is owner-only even for its author');
select pg_temp.login(1);
select is((select count(*)::int from public.file_resource_versions where id=pg_temp.vid('rejected')),1,'owner retains rejected scouting history without deletion');
select pg_temp.login(2);
select lives_ok($$select pg_temp.keep('successor',public.file_reserve(pg_temp.t(),pg_temp.id(1),'scouting',pg_temp.game(),pg_temp.id(12),100,'SYNTHETIC SUCCESSOR','',pg_temp.vid('pdf')))$$,'successor uses new immutable object identity');
select is((select published_version_id from public.file_resources where id=pg_temp.id(1)),pg_temp.vid('pdf'),'old approved bytes remain current during successor upload');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(1),'practice',pg_temp.play(),pg_temp.id(13),100,'RELINK')$$,'42501',null,'existing resource cannot change target kind');
select pg_temp.login(4);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(3),'practice',pg_temp.play(),pg_temp.id(13),10485761,'OVERSIZED CLIP')$$,'22023',null,'clip ceiling rejects10MiB plus one');
select lives_ok($$select pg_temp.keep('clip',public.file_reserve(pg_temp.t(),pg_temp.id(3),'practice',pg_temp.play(),pg_temp.id(13),100,'SYNTHETIC CLIP'))$$,'unrestricted clip uploader reserves published-play target');
select public.file_upload_access(pg_temp.id(13));
reset role;set local role service_role;
select public.file_worker_claim_upload(pg_temp.id(13),false);
select pg_temp.keep('clip',public.file_worker_finish(pg_temp.id(13),100,repeat('c',64),'video/mp4','{"duration":2,"width":640,"height":480,"videoCodec":"h264","audioCodec":null}'));
reset role;set local role authenticated;select pg_temp.login(4);
select lives_ok($$select pg_temp.keep('clip',public.file_transition(pg_temp.t(),pg_temp.vid('clip'),pg_temp.rev('clip'),'publish'))$$,'practice.upload grants byte-specific own-author bypass without per-download approval');
select pg_temp.login(3);
select lives_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('clip'),pg_temp.id(22))$$,'active member can retrieve current published clip');
select pg_temp.login(7);
select throws_ok($$select public.file_transition(pg_temp.t(),pg_temp.vid('successor'),pg_temp.rev('successor'),'approve')$$,'42501',null,'legacy inspector cannot approve another contributor');
select pg_temp.login(5);
select is((select count(*)::int from public.file_resource_versions),0,'nonmember sees no file metadata');
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(4),'practice',pg_temp.play(),pg_temp.id(14),100,'NONMEMBER')$$,'42501',null,'nonmember reserve denied');
select pg_temp.login(6);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('clip'),pg_temp.id(23))$$,'42501',null,'removed member retrieval denied');
reset role;
update public.capability_grants set revoked_at=now() where user_id='e1000000-0000-4000-8000-000000000008' and capability='scouting.read';
set local role authenticated;select pg_temp.login(8);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(24))$$,'42501',null,'revoked read grant immediately blocks future delivery');
select pg_temp.login(1);
select throws_ok($$select public.file_archive(pg_temp.t(),pg_temp.id(1),pg_temp.id(999))$$,'40001',null,'stale archive cannot hide newer publication');
select lives_ok($$select public.file_archive(pg_temp.t(),pg_temp.id(1),pg_temp.vid('pdf'))$$,'owner archives while retaining exact accepted history');
select lives_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(25))$$,'owner retains archived report access');
select pg_temp.login(2);
select is((select count(*)::int from public.file_resource_versions where resource_id=pg_temp.id(1)),0,'archive hides own old pending report from ordinary contributor');
reset role;
set local role service_role;
select throws_ok($$select public.file_worker_claim_upload(pg_temp.id(12),true)$$,'42501',null,'archive stops pending worker finalization/reconciliation');
reset role;
select throws_ok($$delete from public.file_resources where id=pg_temp.id(1)$$,'42501',null,'resource deletion unavailable');
select throws_ok($$update public.file_resource_versions set sha256=repeat('d',64) where id=pg_temp.vid('pdf')$$,'42501',null,'trusted direct update cannot rewrite approved receipt');
-- A reserved download is denied if authority disappears before the byte request.
update public.team_memberships set status='removed' where team_id=pg_temp.t() and user_id='e1000000-0000-4000-8000-000000000003';
set local role service_role;
select throws_ok($$select public.file_worker_claim_delivery(pg_temp.id(22))$$,'42501',null,'revocation after reservation is rechecked before actual byte retrieval');
reset role;
update auth.sessions set not_after=now()-interval '1 hour' where user_id='e1000000-0000-4000-8000-000000000004';
set local role authenticated;select pg_temp.login(4);
select is((select count(*)::int from public.file_resource_versions),0,'expired session cannot read even published clips');
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('clip'),pg_temp.id(26))$$,'42501',null,'expired session cannot reserve byte retrieval');
reset role;
update team_private.file_budget set transfer_limit=transfer_charged where id;
set local role authenticated;select pg_temp.login(1);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('clip'),pg_temp.id(29))$$,'P0001',null,'aggregate exhausted transfer rejects owner without hiding history');
reset role;
update team_private.file_budget set storage_limit=300 where id;
set local role authenticated;select pg_temp.login(9);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(4),'practice',pg_temp.play(),pg_temp.id(14),1,'FULL')$$,'P0001',null,'retained and pending reservations consume aggregate allowance');
reset role;
update team_private.file_uploads set expires_at=now()-interval '1 minute' where operation_id=pg_temp.id(12);
update team_private.file_budget set storage_limit=300 where id;
set local role authenticated;select pg_temp.login(2);
select throws_ok($$select public.file_reserve(pg_temp.t(),pg_temp.id(5),'scouting',pg_temp.game(),pg_temp.id(15),1,'EXPIRED')$$,'P0001',null,'expired upload never frees possibly occupied bytes');
reset role;
update team_private.file_budget set known_until=now()-interval '1 minute' where id;
set local role authenticated;select pg_temp.login(1);
select throws_ok($$select public.file_delivery(pg_temp.t(),pg_temp.vid('pdf'),pg_temp.id(27))$$,'P0001',null,'stale capacity blocks even owner future transfers');
select ok((select count(*)>0 from public.team_audit_events where team_id=pg_temp.t() and action like 'file.%'),'file lifecycle leaves protected audit history');
select * from finish();
rollback;
